#include <stdio.h>

int main(void) {
    int a = 7, b = 2;
    printf("%d + %d = %d\n", a, b, a + b);
    printf("%d - %d = %d\n", a, b, a - b);
    printf("%d * %d = %d\n", a, b, a * b);
    printf("%d / %d = %d\n", a, b, a / b);
    printf("%d %% %d = %d\n", a, b, a % b);
    printf("%.1f / %d = %.2f\n", 7.0, b, 7.0 / b);
    return 0;
}

