#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int maxOf(int a, int b) {
    return a > b ? a : b;
}

int main(void) {
    printf("3 + 5 = %d\n", add(3, 5));
    printf("较大的是 %d\n", maxOf(12, 7));
    return 0;
}

tasks.answer:
