#include <stdio.h>

int main(void) {
    int scores[5] = {88, 92, 79, 95, 67};
    int sum = 0, max = scores[0];
    for (int i = 0; i < 5; i++) {
        sum += scores[i];
        if (scores[i] > max) max = scores[i];
    }
    printf("总分 %d\n", sum);
    printf("平均 %.1f\n", sum / 5.0);
    printf("最高 %d\n", max);
    return 0;
}

